
`timescale 1ns/1ps

module fir_filter #(
    parameter DATA_WIDTH  = 16,
    parameter COEFF_WIDTH = 16,
    parameter ACC_WIDTH   = 40
)(
    input  wire clk,
    input  wire rst,
    input  wire signed [DATA_WIDTH-1:0] x_in,
    input  wire valid_in,
    output reg  signed [DATA_WIDTH-1:0] y_out,
    output reg  valid_out
);

    localparam NTAPS = 32;

    // Q1.15 coefficients generated by MATLAB
    reg signed [COEFF_WIDTH-1:0] coeff [0:NTAPS-1];

    // Previous input samples
    reg signed [DATA_WIDTH-1:0] delay_line [0:NTAPS-1];

    // Arithmetic signals
    reg signed [DATA_WIDTH-1:0] sample;
    reg signed [31:0] sample_ext;
    reg signed [31:0] coeff_ext;
    reg signed [31:0] product;
    reg signed [ACC_WIDTH-1:0] accumulator;
    reg signed [ACC_WIDTH-1:0] scaled_acc;

    integer k;
    integer j;

    initial begin
        coeff[0]  = 16'sd31;
        coeff[1]  = -16'sd15;
        coeff[2]  = -16'sd80;
        coeff[3]  = -16'sd127;
        coeff[4]  = -16'sd71;
        coeff[5]  = 16'sd139;
        coeff[6]  = 16'sd407;
        coeff[7]  = 16'sd470;
        coeff[8]  = 16'sd77;
        coeff[9]  = -16'sd720;
        coeff[10] = -16'sd1409;
        coeff[11] = -16'sd1209;
        coeff[12] = 16'sd432;
        coeff[13] = 16'sd3341;
        coeff[14] = 16'sd6520;
        coeff[15] = 16'sd8597;
        coeff[16] = 16'sd8597;
        coeff[17] = 16'sd6520;
        coeff[18] = 16'sd3341;
        coeff[19] = 16'sd432;
        coeff[20] = -16'sd1209;
        coeff[21] = -16'sd1409;
        coeff[22] = -16'sd720;
        coeff[23] = 16'sd77;
        coeff[24] = 16'sd470;
        coeff[25] = 16'sd407;
        coeff[26] = 16'sd139;
        coeff[27] = -16'sd71;
        coeff[28] = -16'sd127;
        coeff[29] = -16'sd80;
        coeff[30] = -16'sd15;
        coeff[31] = 16'sd31;
    end

    // Combinational FIR sum
    // tap 0 uses current input; other taps use stored samples.
    always @* begin
        accumulator = {ACC_WIDTH{1'b0}};
        sample      = {DATA_WIDTH{1'b0}};
        sample_ext  = 32'sd0;
        coeff_ext   = 32'sd0;
        product     = 32'sd0;

        for (k = 0; k < NTAPS; k = k + 1) begin
            if (k == 0)
                sample = x_in;
            else
                sample = delay_line[k-1];

            // Explicit sign extension before multiplication
            sample_ext = {{(32-DATA_WIDTH){sample[DATA_WIDTH-1]}},
                           sample};

            coeff_ext = {{(32-COEFF_WIDTH){coeff[k][COEFF_WIDTH-1]}},
                          coeff[k]};

            product = sample_ext * coeff_ext;

            accumulator = accumulator +
                {{(ACC_WIDTH-32){product[31]}}, product};
        end

        // Convert Q1.30 accumulated result to output scale
        scaled_acc = accumulator >>> 15;
    end

    // Registered output and input history
    always @(posedge clk) begin
        if (rst) begin
            for (j = 0; j < NTAPS; j = j + 1)
                delay_line[j] <= {DATA_WIDTH{1'b0}};

            y_out     <= {DATA_WIDTH{1'b0}};
            valid_out <= 1'b0;
        end
        else begin
            valid_out <= valid_in;

            if (valid_in) begin
                for (j = NTAPS-1; j > 0; j = j - 1)
                    delay_line[j] <= delay_line[j-1];

                delay_line[0] <= x_in;

                // Saturate to signed output range
                if (scaled_acc > 32767)
                    y_out <= {1'b0, {(DATA_WIDTH-1){1'b1}}};
                else if (scaled_acc < -32768)
                    y_out <= {1'b1, {(DATA_WIDTH-1){1'b0}}};
                else
                    y_out <= scaled_acc[DATA_WIDTH-1:0];
            end
        end
    end

endmodule
